#!/usr/bin/env node
/**
 * Generates TypeScript types from the backend contract (spec §29.1):
 *   ../docs/openapi.json                 -> src/api/types.gen.ts   (REST bodies)
 *   ../docs/schemas/replay.schema.json   -> src/api/wire.gen.ts    (Replay file)
 *   ../docs/schemas/ws_messages.schema.json                         (WebSocket messages)
 * Regenerate the inputs first with `python scripts/export_schemas.py`.
 * `--check` fails if the generated files are stale.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { compile } from "json-schema-to-typescript";

const ROOT = join(import.meta.dirname, "..");
const DOCS = join(ROOT, "..", "docs");
const check = process.argv.includes("--check");
const BANNER = "/* AUTO-GENERATED by scripts/gen_types.mjs from docs/ — do not edit. */\n";

const readJson = (p) => JSON.parse(readFileSync(p, "utf-8"));
const opts = { bannerComment: "", additionalProperties: false, declareExternallyReferenced: true, unreachableDefinitions: true, strictIndexSignatures: false };

function rewriteRefs(node, from, to) {
  if (Array.isArray(node)) return node.map((n) => rewriteRefs(n, from, to));
  if (node && typeof node === "object") {
    return Object.fromEntries(
      Object.entries(node).map(([k, v]) => [k, k === "$ref" && typeof v === "string" ? v.replace(from, to) : rewriteRefs(v, from, to)]),
    );
  }
  return node;
}

async function fromOpenApi() {
  const spec = readJson(join(DOCS, "openapi.json"));
  const defs = rewriteRefs(spec.components.schemas, "#/components/schemas/", "#/$defs/");
  const root = { title: "ApiSchemas", type: "object", additionalProperties: false, $defs: defs, properties: Object.fromEntries(Object.keys(defs).map((k) => [k, { $ref: `#/$defs/${k}` }])) };
  return compile(root, "ApiSchemas", opts);
}

async function fromSchemaFile(name, title) {
  const schema = readJson(join(DOCS, "schemas", name));
  return compile({ ...schema, title }, title, opts);
}

async function wire() {
  const replay = await fromSchemaFile("replay.schema.json", "Replay");
  const ws = readJson(join(DOCS, "schemas", "ws_messages.schema.json"));
  const wsDefs = rewriteRefs(ws.$defs, "#/$defs/", "#/$defs/");
  const root = { title: "WsMessages", type: "object", additionalProperties: false, $defs: wsDefs, properties: Object.fromEntries(Object.keys(wsDefs).map((k) => [k, { $ref: `#/$defs/${k}` }])) };
  const wsTs = await compile(root, "WsMessages", opts);
  // ReplayFrame etc. are declared by both outputs; keep the replay copy and drop the duplicates from ws.
  const declared = new Set([...replay.matchAll(/export (?:interface|type) (\w+)/g)].map((m) => m[1]));
  const blocks = wsTs.split(/\n(?=export (?:interface|type) )/).filter((b) => {
    const m = b.match(/^export (?:interface|type) (\w+)/);
    return !(m && declared.has(m[1]));
  });
  return replay + "\n" + blocks.join("\n");
}

const outputs = {
  [join(ROOT, "src", "api", "types.gen.ts")]: BANNER + (await fromOpenApi()),
  [join(ROOT, "src", "api", "wire.gen.ts")]: BANNER + (await wire()),
};
let stale = false;
for (const [path, text] of Object.entries(outputs)) {
  if (check) {
    if (!existsSync(path) || readFileSync(path, "utf-8") !== text) {
      console.error(`stale: ${path}`);
      stale = true;
    }
  } else {
    writeFileSync(path, text);
    console.log(`wrote ${path}`);
  }
}
process.exit(stale ? 1 : 0);
